/** VaTextReveal 的类型定义 */

export interface TextRevealProps {
  /** 要入场的文本 */
  text: string;
  /** 切分粒度：逐词 / 逐字（中文自动逐字效果好） */
  by?: "word" | "char";
  /** 两段之间的间隔 ms */
  stagger?: number;
  /** 首段等待 ms */
  delay?: number;
  /** 单段浮现时长 ms */
  duration?: number;
  /** 渲染标签 */
  as?: "span" | "p" | "h1" | "h2" | "h3";
  /** 只在首次进入视口时播放 */
  once?: boolean;
}

import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import type { TextRevealProps } from "./types";

/** VaTextReveal 的状态逻辑：切分片段 + IntersectionObserver 触发浮现 */
export function useTextReveal(props: TextRevealProps) {
  const shown = ref(false);
  const root = ref<HTMLElement | null>(null);
  let io: IntersectionObserver | null = null;

  /** 按粒度切分（保留空格节奏） */
  const pieces = computed(() => {
    if (props.by === "char") return Array.from(props.text);
    return props.text.split(/(\s+)/).filter((s) => s.length > 0);
  });

  onMounted(() => {
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
      shown.value = true;
      return;
    }
    if (typeof IntersectionObserver === "undefined") {
      shown.value = true;
      return;
    }
    io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          shown.value = true;
          if (props.once) {
            io?.disconnect();
            io = null;
          }
        } else if (!props.once) {
          shown.value = false;
        }
      },
      { threshold: 0.3 },
    );
    io.observe(root.value!);
  });

  onBeforeUnmount(() => io?.disconnect());

  /** 单段的过渡样式：错峰延迟 */
  function pieceStyle(i: number) {
    return {
      transitionDelay: `${props.delay + i * props.stagger}ms`,
      transitionDuration: `${props.duration}ms`,
    };
  }

  return { root, shown, pieces, pieceStyle };
}
